  if t['type']=='hinge':v=np.maximum(v-t['knot'],0)
  out=out+t['coef']*v
 for t in model['interactions']:
  j,k=[INPUTS.index(a) for a in t['inputs']]
  if 'knots' in t:
   v=np.maximum(X[:,j]-t['knots'][0],0)*np.maximum(X[:,k]-t['knots'][1],0)
  else:v=X[:,j]*X[:,k]
  out=out+t['coef']*v
